COMPLETE_LOCALES: frozenset[str] = frozenset(TRANSLATIONS)


def _log(exc: Exception) -> None:
    report(exc, "i18n")


def _resolve(code: str) -> str:
    """Map an Anki locale (es_ES, en-GB, pt_BR, or_OR, tl...) to our tables."""
    code = code.replace("-", "_")
    parts = code.split("_")
    primary = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 else ""
    if primary == "zh":
        return "zh_TW" if region in ("TW", "HK", "MO") or "HANT" in code.upper() else "zh_CN"
    if primary == "pt":
        return "pt_PT" if region == "PT" else "pt_BR"
    if primary in ("fil", "tl"):
        return "fil"
    return primary if primary in TRANSLATIONS else FALLBACK


@lru_cache(maxsize=1)
def current_lang() -> str:
    """Anki only applies a language change after a restart, so this is cached."""
    try:
        import anki.lang

        raw = (
            getattr(anki.lang, "current_lang", None)
            or getattr(anki.lang, "currentLang", None)
            or ""
        )
        code = raw if isinstance(raw, str) else ""
        return _resolve(code)
    except Exception as exc:
        _log(exc)
        return FALLBACK


def t(key: str) -> str:
    table = TRANSLATIONS.get(current_lang(), TRANSLATIONS[FALLBACK])
    value = table.get(key)
    if value is not None:
        return value
    return TRANSLATIONS[FALLBACK].get(key, key)


def streak_label(streak: int) -> str:
    """Text for a streak milestone; empty when this streak is not a milestone."""
    if not is_celebration_milestone(streak):
        return ""
    return t("streak").format(count=streak)


def record_label(count: int) -> str:
    """Text shown the moment a personal record is beaten."""
    return t("record").format(count=count)


def record_value_label(count: int) -> str:
    """Value shown after "Your current record:" in the settings dialog."""
    return t("opt_record_value").format(count=count)
